DELETE FROM `catalog_items` WHERE `item_id` REGEXP '^11[23][0-9]{3}$';
DELETE FROM `catalog_pages` WHERE `id` BETWEEN 964000 AND 964999;
DELETE FROM `furniture` WHERE `id` BETWEEN 112000 AND 113999;


-- Furniture. id == sprite_id; interaction_modes_count is the states the bundle draws.


-- The Neopets already on Promotional join Zipto's in the new set. Matched as
-- text (item_id is a varchar), so no row is converted to a number.
UPDATE `catalog_items` `ci`
    JOIN `furniture` `f` ON `ci`.`item_id` = CAST(`f`.`id` AS CHAR)
    SET `ci`.`page_id` = 964003
    WHERE `ci`.`page_id` = @promotional AND `f`.`item_name` LIKE 'neopets\_%';

SET @n := 0;
UPDATE `catalog_pages` SET `order_num` = (@n := @n + 1)
    WHERE `parent_id` = @customs
    ORDER BY `caption`;

SET @n := 0;
UPDATE `catalog_pages` SET `order_num` = (@n := @n + 1)
    WHERE `parent_id` = @themes
    ORDER BY (`caption` = 'More Themes'), `caption`;

SET @n := 0;
UPDATE `catalog_pages` SET `order_num` = (@n := @n + 1)
    WHERE `parent_id` = @bonus
    ORDER BY `caption`;
